do $$ declare r record; begin for r in select p.oid,n.nspname,p.proname,pg_get_function_identity_arguments(p.oid) args from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('business_add_program_location','business_add_program_member','business_change_member_role','business_create_location','business_create_media','business_create_partner_program','business_create_partnership','business_delete_media','business_delete_partner_program','business_delete_partnership','business_enroll_program_user','business_invite_member','business_manage_location','business_remove_member','business_remove_program_location','business_request_partner_agreement','business_revoke_program_member','business_set_location_active','business_set_location_amenity','business_set_partner_enabled','business_set_partner_program_access','business_transfer_ownership','business_update_location','business_update_media','business_update_partner_program','business_update_partnership','business_send_custom_notification','business_set_qr_active','business_update_custom_qr','set_business_qr_customization','set_business_qr_status','set_location_qr_customization','create_business_qr','ensure_location_qr','record_qr_attribution','quest_trigger_qr','redeem_qr_code','resolve_custom_qr_action','consume_single_use_qr') loop execute format('revoke execute on function %I.%I(%s) from anon',r.nspname,r.proname,r.args); execute format('grant execute on function %I.%I(%s) to authenticated',r.nspname,r.proname,r.args); end loop; end $$;
